using Clary.Api.Identity;
using System.Text;using System.Text.Json.Nodes;using System.Security.Cryptography;using Npgsql;
namespace Clary.Api;
public sealed record InventoryDocumentState(Guid? DocumentId,IReadOnlyList<ChatProject> Candidates);
public sealed record InventoryDocumentLink(Guid? DocumentId=null,bool CreateNew=false,string Category="Computer");
public sealed class InventoryDocumentation(NpgsqlDataSource db){
 public static string FolderName(string category)=>category switch{"Computer"=>"Computers","Printer"=>"Printers","Monitor"=>"Monitors","Network"=>"Network","Accessory"=>"Accessories",_=>category.StartsWith("custom-")&&Guid.TryParseExact(category[7..],"N",out _)?category:throw new ArgumentException("Choose a valid asset type.")};
 public async Task<InventoryDocumentState> GetAsync(CompanyContext context,CancellationToken ct,string category="Computer"){
  var folderName=FolderName(category);if(category.StartsWith("custom-")){await using var type=CompanyCommand.Create(context,"SELECT name FROM asset_types WHERE company_id=@company AND code=@code",db);type.Parameters.AddWithValue("code",category);folderName=await type.ExecuteScalarAsync(ct) as string??throw new ArgumentException("Choose a valid asset type.");}
  Guid? mapped;await using(var q=CompanyCommand.Create(context,"SELECT document_id FROM inventory_documentation WHERE company_id=@company AND category=@category",db)){q.Parameters.AddWithValue("category",category);mapped=await q.ExecuteScalarAsync(ct) as Guid?;}
  if(mapped.HasValue){var resolved=await new LibraryOperations(db).ResolveAsync(context,mapped.Value,ct);if(resolved.HasValue)return new(resolved,[]);}
  await using var c=CompanyCommand.Create(context,"SELECT d.id,d.title FROM documents d JOIN document_folders p ON p.document_id=d.id JOIN library_folders f ON f.id=p.folder_id JOIN library_folders root ON root.id=f.parent_id WHERE d.company_id=@company AND p.company_id=@company AND f.company_id=@company AND root.company_id=@company AND root.parent_id IS NULL AND root.name='Inventory' AND f.name=@folder AND NOT d.archived AND d.filename LIKE 'wiki/%' ORDER BY d.title,d.id",db);c.Parameters.AddWithValue("folder",folderName);await using var r=await c.ExecuteReaderAsync(ct);var candidates=new List<ChatProject>();while(await r.ReadAsync(ct))candidates.Add(new(r.GetGuid(0),r.GetString(1)));return new(null,candidates);
 }
 public async Task<InventoryDocumentState> LinkAsync(CompanyContext context,Guid? selected,bool createNew,CancellationToken ct,string category="Computer"){
  var folderName=FolderName(category);if(category.StartsWith("custom-")){await using var type=CompanyCommand.Create(context,"SELECT name FROM asset_types WHERE company_id=@company AND code=@code",db);type.Parameters.AddWithValue("code",category);folderName=await type.ExecuteScalarAsync(ct) as string??throw new ArgumentException("Choose a valid asset type.");}
  await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);await AccountPermissions.RevalidateAsync(conn,tx,context,CompanyCapability.Write,ct);await using(var l=CompanyCommand.Create(context,"SELECT pg_advisory_xact_lock(hashtextextended(@company::text||':inventory-docs',0))",conn,tx))await l.ExecuteNonQueryAsync(ct);
  // The lock serializes provisioning; resolve the latest immutable revision before linking.
  if(selected is Guid requested){await using var check=CompanyCommand.Create(context,"SELECT 1 FROM documents WHERE company_id=@company AND id=@id",conn,tx);check.Parameters.AddWithValue("id",requested);if(await check.ExecuteScalarAsync(ct) is null)throw new CompanyResourceMissing();}
  var state=await GetAsync(context,ct,category);if(state.DocumentId.HasValue)return state;
  if(!selected.HasValue&&(createNew||state.Candidates.Count==0)){await using var assets=CompanyCommand.Create(context,"SELECT 1 FROM inventory_assets WHERE company_id=@company AND category=@category LIMIT 1",conn,tx);assets.Parameters.AddWithValue("category",category);if(await assets.ExecuteScalarAsync(ct) is null)throw new ArgumentException("Add the first asset of this type before creating its inventory documentation.");}
  async Task<Guid> Folder(string name,Guid? parent){await using var q=CompanyCommand.Create(context,"SELECT id FROM library_folders WHERE company_id=@company AND name=@name AND parent_id IS NOT DISTINCT FROM @parent ORDER BY id LIMIT 1",conn,tx);q.Parameters.AddWithValue("name",name);q.Parameters.AddWithValue("parent",NpgsqlTypes.NpgsqlDbType.Uuid,(object?)parent??DBNull.Value);if(await q.ExecuteScalarAsync(ct) is Guid found)return found;var id=Guid.NewGuid();q.CommandText="INSERT INTO library_folders(company_id,id,name,parent_id) VALUES(@company,@id,@name,@parent)";q.Parameters.AddWithValue("id",id);await q.ExecuteNonQueryAsync(ct);return id;}
  var root=await Folder("Inventory",null);var folder=await Folder(folderName,root);
  if(!selected.HasValue&&!createNew&&state.Candidates.Count>0){await tx.CommitAsync(ct);return state;}
  string title=(category.StartsWith("custom-")?folderName:category)+" inventory",version="1.0";JsonArray nodes=new();Guid? old=null;
  if(selected.HasValue){if(!state.Candidates.Any(c=>c.Id==selected.Value))throw new CompanyResourceMissing();await using var q=CompanyCommand.Create(context,"SELECT title,version,rich_content,canonical_text,indexing FROM documents WHERE company_id=@company AND id=@id AND NOT archived AND filename LIKE 'wiki/%' FOR UPDATE",conn,tx);q.Parameters.AddWithValue("id",selected.Value);await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new CompanyResourceMissing();if(r.GetString(4)=="indexing")throw new ArgumentException("Wait for indexing before linking this page.");title=r.GetString(0);version=decimal.TryParse(r.GetString(1),System.Globalization.NumberStyles.Number,System.Globalization.CultureInfo.InvariantCulture,out var v)?(v+.1m).ToString("0.0",System.Globalization.CultureInfo.InvariantCulture):r.GetString(1)+" linked";nodes=r.IsDBNull(2)?new JsonArray(new JsonObject{{"type","p"},{"children",new JsonArray(new JsonObject{{"type","text"},{"text",r.GetString(3)}})}}):JsonNode.Parse(r.GetString(2))!.AsArray();old=selected.Value;}
  if(!nodes.Any(n=>n?["type"]?.GetValue<string>()=="inventory"&&n?["category"]?.GetValue<string>()==category))nodes.Add(new JsonObject{{"type","inventory"},{"category",category}});
  var rich=RichDocument.Read(nodes.ToJsonString());var idNew=Guid.NewGuid();
  await using(var q=CompanyCommand.Create(context,"INSERT INTO documents(company_id,id,title,version,approval,indexing,filename,content_hash,canonical_text,rich_content,supported_models) VALUES(@company,@id,@title,@version,'draft','pending',@filename,@hash,@text,@content,@models)",conn,tx)){q.Parameters.AddWithValue("id",idNew);q.Parameters.AddWithValue("title",title);q.Parameters.AddWithValue("version",version);q.Parameters.AddWithValue("filename","wiki/"+idNew+".md");q.Parameters.AddWithValue("hash",Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(rich.Text))));q.Parameters.AddWithValue("text",rich.Text);q.Parameters.AddWithValue("content",rich.Content);q.Parameters.AddWithValue("models",EpsonModels.Extract(rich.Text));await q.ExecuteNonQueryAsync(ct);}
  await CompanyFiles.LinkImagesAsync(context,conn,tx,idNew,rich.Content,ct);
  if(old.HasValue){await using(var q=CompanyCommand.Create(context,"UPDATE document_folders SET document_id=@new WHERE company_id=@company AND document_id=@old",conn,tx)){q.Parameters.AddWithValue("new",idNew);q.Parameters.AddWithValue("old",old.Value);await q.ExecuteNonQueryAsync(ct);}await using(var q=CompanyCommand.Create(context,"UPDATE documents SET archived=true,approval='revoked',replaced_by=@new WHERE company_id=@company AND id=@old",conn,tx)){q.Parameters.AddWithValue("new",idNew);q.Parameters.AddWithValue("old",old.Value);await q.ExecuteNonQueryAsync(ct);}}
  else{await using var q=CompanyCommand.Create(context,"INSERT INTO document_folders(company_id,document_id,folder_id) VALUES(@company,@doc,@folder)",conn,tx);q.Parameters.AddWithValue("doc",idNew);q.Parameters.AddWithValue("folder",folder);await q.ExecuteNonQueryAsync(ct);}
  await using(var q=CompanyCommand.Create(context,"INSERT INTO inventory_documentation(company_id,category,document_id) VALUES(@company,@category,@id) ON CONFLICT(company_id,category) DO UPDATE SET document_id=EXCLUDED.document_id",conn,tx)){q.Parameters.AddWithValue("category",category);q.Parameters.AddWithValue("id",idNew);await q.ExecuteNonQueryAsync(ct);}await tx.CommitAsync(ct);return new(idNew,[]);
 }

 public async Task EnsureAllAsync(CompanyContext context,CancellationToken ct){
  await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);
  await AccountPermissions.RevalidateAsync(conn,tx,context,CompanyCapability.Write,ct);
  var codes=new List<string>();await using(var q=CompanyCommand.Create(context,"SELECT code FROM asset_types WHERE company_id=@company AND EXISTS(SELECT 1 FROM inventory_assets a WHERE a.company_id=@company AND a.asset_type_id=asset_types.id) ORDER BY sort_order,id",conn,tx)){await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))codes.Add(r.GetString(0));}
  foreach(var code in codes)await EnsureAsync(context,conn,tx,code,ct);await tx.CommitAsync(ct);
 }
 public static async Task EnsureAsync(CompanyContext context,NpgsqlConnection conn,NpgsqlTransaction tx,string category,CancellationToken ct){
  var folderName=FolderName(category);string typeName=category;await using(var t=CompanyCommand.Create(context,"SELECT name FROM asset_types WHERE company_id=@company AND code=@code",conn,tx)){t.Parameters.AddWithValue("code",category);typeName=await t.ExecuteScalarAsync(ct) as string??throw new ArgumentException("Choose a valid asset type.");}if(category.StartsWith("custom-"))folderName=typeName;await using(var q=CompanyCommand.Create(context,"SELECT pg_advisory_xact_lock(hashtextextended(@company::text||':inventory-docs',0))",conn,tx))await q.ExecuteNonQueryAsync(ct);
  await using(var q=CompanyCommand.Create(context,"SELECT document_id FROM inventory_documentation WHERE company_id=@company AND category=@category",conn,tx)){q.Parameters.AddWithValue("category",category);if(await q.ExecuteScalarAsync(ct) is Guid)return;}
  async Task<Guid> Folder(string name,Guid? parent){await using var q=CompanyCommand.Create(context,"SELECT id FROM library_folders WHERE company_id=@company AND name=@name AND parent_id IS NOT DISTINCT FROM @parent ORDER BY id LIMIT 1",conn,tx);q.Parameters.AddWithValue("name",name);q.Parameters.AddWithValue("parent",NpgsqlTypes.NpgsqlDbType.Uuid,(object?)parent??DBNull.Value);if(await q.ExecuteScalarAsync(ct) is Guid found)return found;var id=Guid.NewGuid();q.CommandText="INSERT INTO library_folders(company_id,id,name,parent_id) VALUES(@company,@id,@name,@parent)";q.Parameters.AddWithValue("id",id);await q.ExecuteNonQueryAsync(ct);return id;}
  var root=await Folder("Inventory",null);var folder=await Folder(folderName,root);var idNew=Guid.NewGuid();var rich=RichDocument.Read(new JsonArray(new JsonObject{{"type","inventory"},{"category",category}}).ToJsonString());
  await using(var q=CompanyCommand.Create(context,"INSERT INTO documents(company_id,id,title,version,approval,indexing,filename,content_hash,canonical_text,rich_content) VALUES(@company,@id,@title,'1.0','draft','pending',@file,@hash,@text,@content)",conn,tx)){q.Parameters.AddWithValue("id",idNew);q.Parameters.AddWithValue("title",typeName+" inventory");q.Parameters.AddWithValue("file","wiki/"+idNew+".md");q.Parameters.AddWithValue("hash",Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(rich.Text))));q.Parameters.AddWithValue("text",rich.Text);q.Parameters.AddWithValue("content",rich.Content);await q.ExecuteNonQueryAsync(ct);}
  await using(var q=CompanyCommand.Create(context,"INSERT INTO document_folders(company_id,document_id,folder_id) VALUES(@company,@id,@folder)",conn,tx)){q.Parameters.AddWithValue("id",idNew);q.Parameters.AddWithValue("folder",folder);await q.ExecuteNonQueryAsync(ct);}
  await using(var q=CompanyCommand.Create(context,"INSERT INTO inventory_documentation(company_id,category,document_id) VALUES(@company,@category,@id)",conn,tx)){q.Parameters.AddWithValue("category",category);q.Parameters.AddWithValue("id",idNew);await q.ExecuteNonQueryAsync(ct);}
 }
}






